- How would you handle unseen latency values without rebuilding the compression map?
- Compare this approach to a wavelet tree for large domains or streaming data.

## Why This Is Asked

This question evaluates practical knowledge of order-statistics trees for managing dynamic value sets with range queries and per-ID updates—a common pattern in analytics, billing, and HR systems.

## Key Concepts

- Augmented BST (order-statistics tree) with duplicate support via frequency counts
- Range-sum and range-count queries using subtree aggregation
- Hash map for O(1) ID-to-salary lookups, enabling efficient updates and deletions
- Amortized O(log n) operations through balanced tree structure

## Code Example

```javascript
class SalaryTree {
  constructor() {
    this.root = null;
    this.idToSalary = new Map();
  }

  addEmployee(id, salary) {
    this.idToSalary.set(id, salary);
    this.root = this._insert(this.root, salary);
  }

  removeEmployee(id) {
    const salary = this.idToSalary.get(id);
    if (salary === undefined) return;
    this.idToSalary.delete(id);
    this.root = this._remove(this.root, salary);
  }

  updateSalary(id, newSalary) {
    this.removeEmployee(id);
    this.addEmployee(id, newSalary);
  }

  countSalariesInRange(min, max) {
    return this._countRange(this.root, min, max);
  }

  sumSalariesInRange(min, max) {
    return this._sumRange(this.root, min, max);
  }

  kthSalaryInRange(min, max, k) {
    return this._kthRange(this.root, min, max, k);
  }

  _insert(node, salary) {
    if (!node) return new Node(salary);
    if (salary === node.salary) {
      node.freq++;
    } else if (salary < node.salary) {
      node.left = this._insert(node.left, salary);
    } else {
      node.right = this._insert(node.right, salary);
    }
    return this._rebalance(node);
  }

  _remove(node, salary) {
    if (!node) return null;
    if (salary === node.salary) {
      if (node.freq > 1) {
        node.freq--;
        return node;
      }
      return this._merge(node.left, node.right);
    }
    if (salary < node.salary) {
      node.left = this._remove(node.left, salary);
    } else {
      node.right = this._remove(node.right, salary);
    }
    return this._rebalance(node);
  }

  _rebalance(node) {
    this._update(node);
    return node;
  }

  _update(node) {
    node.subtreeSize = node.freq;
    node.subtreeSum = node.salary * node.freq;
    if (node.left) {
      node.subtreeSize += node.left.subtreeSize;
      node.subtreeSum += node.left.subtreeSum;
    }
    if (node.right) {
      node.subtreeSize += node.right.subtreeSize;
      node.subtreeSum += node.right.subtreeSum;
    }
  }

  _merge(left, right) {
    if (!left || !right) return left || right;
    if (left.pri < right.pri) {
      left.right = this._merge(left.right, right);
      this._update(left);
      return left;
    }
    right.left = this._merge(left, right.left);
    this._update(right);
    return right;
  }

  _countRange(node, min, max) {
    if (!node) return 0;
    if (node.salary < min) return this._countRange(node.right, min, max);
    if (node.salary > max) return this._countRange(node.left, min, max);
    const leftCount = node.left ? node.left.subtreeSize : 0;
    const rightCount = node.right ? node.right.subtreeSize : 0;
    return leftCount + node.freq + rightCount;
  }

  _sumRange(node, min, max) {
    if (!node) return 0;
    if (node.salary < min) return this._sumRange(node.right, min, max);
    if (node.salary > max) return this._sumRange(node.left, min, max);
    const leftSum = node.left ? node.left.subtreeSum : 0;
    const rightSum = node.right ? node.right.subtreeSum : 0;
    return leftSum + (node.salary * node.freq) + rightSum;
  }

  _kthRange(node, min, max, k) {
    if (!node) return null;
    if (node.salary < min) return this._kthRange(node.right, min, max, k);
    if (node.salary > max) return this._kthRange(node.left, min, max, k);
    const leftSize = node.left ? node.left.subtreeSize : 0;
    if (k < leftSize) return this._kthRange(node.left, min, max, k);
    if (k < leftSize + node.freq) return node.salary;
    const rightK = k - leftSize - node.freq;
    return this._kthRange(node.right, min, max, rightK);
  }
}

class Node {
  constructor(salary) {
    this.salary = salary;
    this.freq = 1;
    this.subtreeSize = 1;
    this.subtreeSum = salary;
    this.left = null;
    this.right = null;
    this.pri = Math.random();
  }
}
```

## Why This Is Asked
Dynamic connectivity with insertions and deletions is a classic hard problem. This offline approach tests understanding of edge lifetimes and versioning, and how to combine segment trees with DSU rollback for log-scale updates.

## Key Concepts
- DSU with rollback (no path compression) to enable undo.
- Segment tree over time to map edge active intervals to time ranges.
- Offline processing: traverse tree, apply unions, answer leaf queries, then rollback.

## Code Example
```javascript
class RollbackDSU {
  constructor(n){
    this.parent = Array.from({length:n}, (_,i)=>i);
    this.sz = Array(n).fill(1);
    this.ch = [];
  }
  find(x){ while (this.parent[x]!==x) x = this.parent[x]; return x; }
  union(a,b){
    a = this.find(a); b = this.find(b);
    if (a===b){ this.ch.push(null); return; }
    if (this.sz[a] < this.sz[b]) [a,b] = [b,a];
    this.ch.push([b, this.parent[b], a, this.sz[a]]);
    this.parent[b] = a; this.sz[a] += this.sz[b];
  }
  snapshot(){ return this.ch.length; }
  rollback(snap){
    while (this.ch.length > snap){
      const ch = this.ch.pop();
      if (!ch) continue;
      const [b, oldP, a, oldS] = ch;
      this.parent[b] = oldP; this.sz[a] = oldS;
    }
  }
}
```

## Why This Is Asked
This question tests the fundamental understanding of combining data structures to achieve O(1) operations while maintaining an ordering constraint. It evaluates knowledge of hash map + linked list patterns and eviction logic commonly used in caching systems.

## Key Concepts
- HashMap for O(1) key-to-node lookups
- Doubly linked list for maintaining recency order
- Node manipulation for constant-time recency updates
- Edge case handling: missing keys, capacity limits, and duplicate operations

## Code Example
```javascript
class LRUCache {
  constructor(capacity) {
    this.capacity = capacity;
    this.cache = new Map();
    this.head = { prev: null, next: null };
    this.tail = { prev: null, next: null };
    this.head.next = this.tail;
    this.tail.prev = this.head;
  }

  get(key) {
    if (!this.cache.has(key)) return -1;
    const node = this.cache.get(key);
    this._moveToHead(node);
    return node.value;
  }

  put(key, value) {
    if (this.cache.has(key)) {
      const node = this.cache.get(key);
      node.value = value;
      this._moveToHead(node);
    } else {
      const newNode = { key, value, prev: null, next: null };
      this.cache.set(key, newNode);
      this._addToHead(newNode);
      if (this.cache.size > this.capacity) {
        this._removeTail();
      }
    }
  }

  _moveToHead(node) {
    this._removeNode(node);
    this._addToHead(node);
  }

  _addToHead(node) {
    node.prev = this.head;
    node.next = this.head.next;
    this.head.next.prev = node;
    this.head.next = node;
  }

  _removeNode(node) {
    node.prev.next = node.next;
    node.next.prev = node.prev;
  }

  _removeTail() {
    const node = this.tail.prev;
    this._removeNode(node);
    this.cache.delete(node.key);
  }
}
```

## Why This Is Asked
- Introduces a practical autocomplete scenario and a foundational DS.
- Emphasizes handling duplicates and memory management.

## Key Concepts
- Trie with per-node pass-through counts; O(length) ops; dynamic memory.
- Duplicate handling via cnt; pruning unused nodes to bound memory.

## Code Example
```javascript
class TrieNode {
  constructor(){ this.next = new Map(); this.cnt = 0; }
}
class Trie {
  constructor(){ this.root = new TrieNode(); }
  insert(word){ let node=this.root; for(let ch of word){ if(!node.next.has(ch)) node.next.set(ch,new TrieNode()); node = node.next.get(ch); node.cnt++; } }
  erase(word){ let stack=[]; let node=this.root; for(let ch of word){ if(!node.next.has(ch)) return; node = node.next.get(ch); stack.push([node,ch]); } // decrement
    for(let [nd] of stack){ nd.cnt--; }
  }
  countWithPrefix(prefix){ let node=this.root; for(let ch of prefix){ if(!node.next.has(ch)) return 0; node = node.next.get(ch); } return node.cnt; }
}
```

## Why This Is Asked
This question tests the ability to design a dynamic interval data structure that handles duplicates, supports point-sum queries, and enables k-th weight selection—all without scanning all intervals. It combines segment trees with per-node multisets to achieve range updates and efficient multi-set queries.

## Key Concepts
- Segment tree over coordinate-compressed points for efficient range queries
- Per-node multiset of (weight, id) pairs to handle duplicate intervals
- nodeSum aggregation for fast sum queries at any point
- Binary search over the weight domain combined with order statistics for k-th largest queries

## Code Example
```javascript
// Pseudo-implementation sketch for insertInterval/eraseInterval
class IntervalIndex {
  constructor(points) {
    this.tree = new SegmentTree(points.length - 1);
  }

  insertInterval(l, r, w, id) {
    const range = this.getCompressedRange(l, r);
    this.tree.update(range.l, range.r, (node) => {
      node.multiset.add({ weight: w, id });
      node.sum += w;
    });
  }

  eraseInterval(id, w) {
    // Find all intervals containing this id and remove one instance
    this.tree.queryById(id, (node) => {
      node.multiset.delete({ weight: w, id });
      node.sum -= w;
    });
  }

  sumWeightsCoveringPoint(p) {
    const idx = this.compress(p);
    return this.tree.queryPoint(idx, (node) => node.sum);
  }

  kthLargestWeightCoveringPoint(p, k) {
    const idx = this.compress(p);
    const weights = this.tree.getWeightsAt(idx);
    return this.findKthLargest(weights, k);
  }
}
```

